from taf.internal.robot_typecasts import time_to_seconds
import re
from ..util import wrap_result


class RadParamsInterface(object):

    @wrap_result
    def get_bts_rad_parameters(self, type, timeout=120):
        """Get RAD parameters.

        :param integer component: BTS system component number
        :param string type: Requested (SW Config, present in file) or Applied (SW Config + changes made during runtime)
        :param float timeout: Time to wait for positive procedure result.
        
        """
        timeout = time_to_seconds(timeout)
        assert type in ("Requested", "Applied")

        result = self._api_client.execute_infomodel_request("getRadParameters", {"type": type}, timeout)
        return result[0]["flags"]

    def change_bts_rad_parameters(self, component, params, timeout=300):
        """Change RAD parameters.

        :param integer component: BTS system component number
        :param string params: RAD parameters sting (parameter:value,...) eg. 210:5
        :param float timeout: Time to wait for positive procedure result.
        
        """
        component = int(component)
        timeout = time_to_seconds(timeout)
        assert re.match(r"(\d+:\d+,?)+", params), "params does not match requested syntax"

        self._change_rad_params("DynamicChanges", component, params, timeout)

    def change_bts_rad_parameters_permanently(self, component, params, timeout=300):
        """Change RAD parameters permanently.

        :param integer component: BTS system component number
        :param string params: RAD parameters sting (parameter:value,...) eg. 210:5
        :param float timeout: Time to wait for positive procedure result.
        
        """
        component = int(component)
        timeout = time_to_seconds(timeout)
        assert re.match(r"(\d+:\d+,?)+", params), "params does not match requested syntax"

        self._change_rad_params("PersistentChanges", component, params, timeout)

    def change_bts_rad_parameters_with_overreset(self, component, params, timeout=300):
        """Change RAD parameters persistent over one reset.

        :param integer component: BTS system component number
        :param string params: RAD parameters sting (parameter:value,...) eg. 210:5
        :param float timeout: Time to wait for positive procedure result.
        
        """
        component = int(component)
        timeout = time_to_seconds(timeout)
        assert re.match(r"(\d+:\d+,?)+", params), "params does not match requested syntax"

        self._change_rad_params("PersistentOverOneResetChanges", component, params, timeout)

    def reset_bts_rad_parameters(self, component, params, timeout=300):
        """Reset RAD parameters.

        :param integer component: BTS system component number
        :param string params: RAD parameters sting (parameter:value,...) eg. 210:5
        :param float timeout: Time to wait for positive procedure result.
        
        """
        component = int(component)
        timeout = time_to_seconds(timeout)
        assert re.match(r"(\d+:\d+,?)+", params), "params does not match requested syntax"

        self._change_rad_params("FactoryDefaults", component, params, timeout)

    def _change_rad_params(self, setting_type, component, params, timeout):
        changed_params = self._parse_rad_parameters(params)
        self._api_client.execute_procedure(
            "setRadParam", {"btsSwSystemComponent": component, "radSettingType": setting_type, "radParams": changed_params}, timeout)

    def _parse_rad_parameters(self, params):
        changed_params = []
        for param in params.split(","):
            if not param:
                continue
            index, value = param.split(":")
            changed_params.append({"paramIndexNumber": int(index), "paramValue": int(value)})
        return changed_params
